def fibonacci(n):
    if n < 0:
        raise ValueError("Le paramètre n doit être un nombre non négatif.")
    elif n == 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

# Exemple d'utilisation:
n = 10
print(f"Le {n}-ième terme de la suite de Fibonacci est: {fibonacci(n)}")

