class Stack:
    def __init__(self):
        self.items = []

    def push(self, item):
        self.items.append(item)

    def pop(self):
        if not self.is_empty():
            return self.items.pop()
        else:
            raise IndexError("pop from empty stack")

    def is_empty(self):
        return len(self.items) == 0

# Exemple d'utilisation :
stack = Stack()
stack.push(1)
stack.push(2)
print(stack.pop())  # Sortie : 2
print(stack.pop())  # Sortie : 1
print(stack.pop())  # Sortie : IndexError: pop from empty stack

